mapper.update:

UPDATE growth_tg_target SET
  enabled = CASE WHEN fail_streak + 1 >= #{limit} THEN 0 ELSE enabled END,
  disabled_reason = CASE WHEN fail_streak + 1 >= #{limit} THEN #{reason} ELSE disabled_reason END,
  fail_streak = fail_streak + 1,
  updated_at = #{now}
WHERE target_key = #{key}

UPDATE growth_tg_template SET status = #{status}, fingerprint = #{fingerprint},
  approved_by = CASE WHEN #{status} = 'APPROVED' THEN #{by} ELSE approved_by END,
  approved_at = CASE WHEN #{status} = 'APPROVED' THEN #{now} ELSE approved_at END,
  updated_at = #{now}
WHERE kind = #{kind} AND lang = #{lang}
